GVL_IO.DO_GATE1_POWER := GVL.aMechOut[GVL_Const.M_GATE1].qPower;
GVL_IO.DO_GATE1_OPEN := GVL.aMechOut[GVL_Const.M_GATE1].qOpen;
GVL_IO.DO_GATE1_RESET := GVL.aMechOut[GVL_Const.M_GATE1].qReset;
GVL_IO.DO_GATE1_CLOSE := GVL.aMechOut[GVL_Const.M_GATE1].qClose;
GVL_IO.DO_FS27_ON := GVL.aMechOut[GVL_Const.M_FS27].qOn;
GVL_IO.DO_FS27_OFF := GVL.aMechOut[GVL_Const.M_FS27].qOff;
GVL_IO.DO_FS27_ENABLE := GVL.aMechOut[GVL_Const.M_FS27].qEnable;
GVL_IO.DO_A19_Q23_RES := FALSE;
GVL_IO.DO_A19_Q24_RES := FALSE;

InterfaceAsPlainText.xhtml:
(* Маршруты (Приложение 5). Пуск: проверка готовности -> предпусковой сигнал ->
   перевод клапанов -> работа (механизмы запускаются от последнего к первому).
   Стоп: снятие требования (останов от первого к последнему с задержками).
   Авария механизма/клапана/бункера маршрута или общая авария - останов маршрута. *)
PROGRAM PRG_Routes
VAR
    xInit     : BOOL;
    r         : INT;
    p         : INT;
    i         : INT;
    v         : INT;
    b         : INT;
    h         : INT;
    k         : INT;
    nL        : INT;
    aPosT     : ARRAY[1..GVL_Const.N_VALVE] OF INT;
    aL        : ARRAY[1..GVL_Const.N_LINK] OF ST_Link;
    aTonPre   : ARRAY[1..GVL_Const.N_ROUTE] OF TON;
    xToggle   : BOOL;
    xStop     : BOOL;
    xConflict : BOOL;
    xFault    : BOOL;
    xBusy     : BOOL;
    xShared   : BOOL;
    xPaused   : BOOL;
    xAllRun   : BOOL;
    xValvesOk : BOOL;
    iBad      : INT;
    wSts      : WORD;
    aNotReady : ARRAY[1..GVL_Const.N_ROUTE] OF BOOL;
END_VAR

ST.xhtml:
(* ---- уставки по умолчанию при первом запуске / потере RETAIN ---- *)
IF GVL_Retain.uInitMagic <> GVL_Const.RETAIN_MAGIC THEN
    GVL_Retain.stGlobPar.uTPreStart := 10;
    GVL_Retain.stGlobPar.uTDksGrace := 5;
    GVL_Retain.stGlobPar.uTDksPulse := 30;
    GVL_Retain.stGlobPar.uTFcFb := 5;
    GVL_Retain.stGlobPar.uTFsStart := 60;
    GVL_Retain.stGlobPar.uTGateMove := 90;
    GVL_Retain.stGlobPar.uSirenOn := 1;
    FOR i := 1 TO GVL_Const.N_MECH DO
        GVL_Retain.aMechPar[i].uTOn := GVL_Const.MECH_CFG[i].uDefTOn;
        GVL_Retain.aMechPar[i].uTOff := GVL_Const.MECH_CFG[i].uDefTOff;
        GVL_Retain.aMechPar[i].uToInterval := 0;
        GVL_Retain.aMechPar[i].wBypass := 0;
    END_FOR
    FOR i := 1 TO GVL_Const.N_VALVE DO
        GVL_Retain.aValvePar[i].uTMove := 30;
    END_FOR
    FOR i := 1 TO GVL_Const.N_BUNKER DO
        GVL_Retain.aBunkerPar[i].wBypass := 0;
        GVL_Retain.aBunkerPar[i].uTDvu := 3;
        GVL_Retain.aBunkerPar[i].uTRestart := 30;
    END_FOR
    GVL_Retain.uInitMagic := GVL_Const.RETAIN_MAGIC;
END_IF

F_SyncUint(uMax := 600, uHmi := GVL_HMI.stHmiG.uTPreStart, uPar := GVL_Retain.stGlobPar.uTPreStart, uShadow := uSh[1]);
F_SyncUint(uMax := 600, uHmi := GVL_HMI.stHmiG.uTDksGrace, uPar := GVL_Retain.stGlobPar.uTDksGrace, uShadow := uSh[2]);
F_SyncUint(uMax := 600, uHmi := GVL_HMI.stHmiG.uTDksPulse, uPar := GVL_Retain.stGlobPar.uTDksPulse, uShadow := uSh[3]);
F_SyncUint(uMax := 600, uHmi := GVL_HMI.stHmiG.uTFcFb, uPar := GVL_Retain.stGlobPar.uTFcFb, uShadow := uSh[4]);
F_SyncUint(uMax := 600, uHmi := GVL_HMI.stHmiG.uTFsStart, uPar := GVL_Retain.stGlobPar.uTFsStart, uShadow := uSh[5]);
F_SyncUint(uMax := 600, uHmi := GVL_HMI.stHmiG.uTGateMove, uPar := GVL_Retain.stGlobPar.uTGateMove, uShadow := uSh[6]);
F_SyncUint(uMax := 1, uHmi := GVL_HMI.stHmiG.uSirenOn, uPar := GVL_Retain.stGlobPar.uSirenOn, uShadow := uSh[7]);

(* ---- такты ---- *)
tonSec(IN := NOT tonSec.Q, PT := T#1S);
GVL.xPulse1s := tonSec.Q;
tonBlink(IN := NOT tonBlink.Q, PT := T#500MS);
IF tonBlink.Q THEN
    xBlinkReq := NOT xBlinkReq;
END_IF
GVL.xBlink := xBlinkReq;
IF GVL.xPulse1s THEN
    GVL_HMI.stHmiG.uHeartbeat := GVL_HMI.stHmiG.uHeartbeat + 1;
END_IF

(* ---- команды панели ---- *)
GVL.xReset := (GVL_HMI.stHmiG.wCmd AND GVL_Const.G_RESET) <> 0;
GVL.xStopAll := (GVL_HMI.stHmiG.wCmd AND GVL_Const.G_STOPALL) <> 0;
IF (GVL_HMI.stHmiG.wCmd AND GVL_Const.G_MUTE) <> 0 OR GVL.xReset THEN
    xSirenLatch := FALSE;
END_IF
GVL.xSetup := (GVL_HMI.stHmiG.wCmd AND GVL_Const.G_SETUP) <> 0;
GVL_HMI.stHmiG.wCmd := GVL_HMI.stHmiG.wCmd AND NOT (GVL_Const.G_RESET OR GVL_Const.G_MUTE OR GVL_Const.G_STOPALL);

(* ---- общие аварии ---- *)
GVL.xSysOn := GVL.xSysOnIn;
wAct := 0;
FOR i := 1 TO 10 DO
    IF NOT GVL.aEStopIn[i] THEN
        wAct := wAct OR SHL(WORD#1, i - 1);
    END_IF
END_FOR
IF NOT GVL.xFireOkIn THEN
    wAct := wAct OR GVL_Const.GA_FIRE;
END_IF
IF NOT GVL.xPhaseOkIn THEN
    wAct := wAct OR GVL_Const.GA_PHASE;
END_IF
xNewG := (wAct AND NOT wAlm) <> 0;
IF GVL.xReset THEN
    wAlm := wAct;
ELSE
    wAlm := wAlm OR wAct;
END_IF
GVL.xGlobalOk := GVL.xSysOn AND wAlm = 0;

wWarn := 0;
IF NOT GVL.xComprOkIn THEN wWarn := wWarn OR GVL_Const.GW_COMPR; END_IF
IF NOT GVL.xCompr2OkIn THEN wWarn := wWarn OR GVL_Const.GW_COMPR2; END_IF
IF NOT GVL.xDryerOkIn THEN wWarn := wWarn OR GVL_Const.GW_DRYER; END_IF
IF NOT GVL.xFsAspPwrIn THEN wWarn := wWarn OR GVL_Const.GW_FSASP; END_IF
IF NOT GVL.xSysOn THEN wWarn := wWarn OR GVL_Const.GW_SYSOFF; END_IF
(* сжатый воздух нужен фотосепаратору *)
GVL.aMechIn[GVL_Const.M_FS27].xAux := GVL.xComprOkIn;

(* ---- сирена и лампа (GVL.xAnyAlarm / xAnyNewAlarm - от механизмов, предыдущий цикл) ---- *)
IF (xNewG OR GVL.xAnyNewAlarm) AND GVL_Retain.stGlobPar.uSirenOn <> 0 THEN
    xSirenLatch := TRUE;
END_IF
(* предпусковой сигнал - прерывистый, звучит всегда *)
GVL.qSiren := xSirenLatch OR (GVL.xPreStart AND GVL.xBlink);
GVL.qLamp := (GVL.xAnyAlarm OR wAlm <> 0) AND (GVL.xBlink OR NOT xSirenLatch);

wSts := 0;
IF GVL.xSysOn THEN wSts := wSts OR GVL_Const.GS_SYSON; END_IF
IF GVL.xGlobalOk THEN wSts := wSts OR GVL_Const.GS_OK; END_IF
IF GVL.xAnyAlarm OR wAlm <> 0 THEN wSts := wSts OR GVL_Const.GS_ALARM; END_IF
IF GVL.qSiren THEN wSts := wSts OR GVL_Const.GS_SIREN; END_IF
IF GVL.xSetup THEN wSts := wSts OR GVL_Const.GS_SETUP; END_IF
IF GVL.xPreStart THEN wSts := wSts OR GVL_Const.GS_PRESTART; END_IF
GVL_HMI.stHmiG.wSts := wSts;
GVL_HMI.stHmiG.wAlm := wAlm;
GVL_HMI.stHmiG.wWarn := wWarn;

InterfaceAsPlainText.xhtml:
(* Общие сигналы: цепь управления, аварийные стопы, пожар, контроль фаз, сброс, наладка,
   сирена и лампа "Авария", секундный импульс, уставки по умолчанию. *)
PROGRAM PRG_System
VAR
    i         : INT;
    wAct      : WORD;
    wAlm      : WORD;
    wWarn     : WORD;
    wSts      : WORD;
    xNewG     : BOOL;
    xSirenLatch : BOOL;
    tonSec    : TON;
    tonBlink  : TON;
    xBlinkReq : BOOL;
    uSh       : ARRAY[1..7] OF UINT;
END_VAR

ST.xhtml:
GVL.nLinks := F_BuildLinks(aPos := GVL.aValvePos, aLinks := GVL.aLinks);

FOR i := 1 TO GVL_Const.N_MECH DO
    GVL.aSuccAuto[i] := TRUE;
    GVL.aSuccMan[i] := TRUE;
    GVL.aPredRun[i] := FALSE;
    GVL.aBlocked[i] := FALSE;
END_FOR

FOR k := 1 TO GVL.nLinks DO
    CASE GVL.aLinks[k].eTo OF
    GVL_Const.LT_MECH:
        IF NOT GVL.aRun[GVL.aLinks[k].iTo] THEN
            GVL.aSuccAuto[GVL.aLinks[k].iFrom] := FALSE;
            GVL.aSuccMan[GVL.aLinks[k].iFrom] := FALSE;
        END_IF
        IF GVL.aRun[GVL.aLinks[k].iFrom] THEN
            GVL.aPredRun[GVL.aLinks[k].iTo] := TRUE;
        END_IF
    GVL_Const.LT_BUNKER:
        (* в автомате полный бункер обрабатывается паузой участка (aBlocked) *)
        IF GVL.aBunkerFull[GVL.aLinks[k].iTo] OR GVL.aBunkerAlarm[GVL.aLinks[k].iTo] THEN
            GVL.aSuccMan[GVL.aLinks[k].iFrom] := FALSE;
        END_IF
    ELSE
        GVL.aSuccAuto[GVL.aLinks[k].iFrom] := FALSE;
        GVL.aSuccMan[GVL.aLinks[k].iFrom] := FALSE;
    END_CASE
END_FOR

(* пауза распространяется только по связям продукта и не проходит через бункеры *)
FOR pass := 1 TO GVL_Const.N_MECH DO
    xChg := FALSE;
    FOR k := 1 TO GVL.nLinks DO
        IF GVL.aLinks[k].xProduct AND NOT GVL.aBlocked[GVL.aLinks[k].iFrom] THEN
            (* CASE, а не AND: в ST операнды AND вычисляются оба, индекс iTo зависит от типа *)
            xStop := FALSE;
            CASE GVL.aLinks[k].eTo OF
            GVL_Const.LT_BUNKER: xStop := GVL.aBunkerFull[GVL.aLinks[k].iTo];
            GVL_Const.LT_MECH:   xStop := GVL.aBlocked[GVL.aLinks[k].iTo];
            END_CASE
            IF xStop THEN
                GVL.aBlocked[GVL.aLinks[k].iFrom] := TRUE;
                xChg := TRUE;
            END_IF
        END_IF
    END_FOR
    IF NOT xChg THEN
        EXIT;
    END_IF
END_FOR

InterfaceAsPlainText.xhtml:
(* Блокировки по фактическим положениям клапанов:
   - aSuccAuto/aSuccMan - все механизмы, на которые подаёт данный, работают;
   - aPredRun - работает механизм, подающий на данный (удержание при останове);
   - aBlocked - полный бункер на выходе участка: пауза от бункера назад до головы участка. *)
PROGRAM PRG_Topology
VAR
    i    : INT;
    k    : INT;
    pass : INT;
    xStop : BOOL;
    xChg : BOOL;
END_VAR

(* Рабочие переменные программы *)
VAR_GLOBAL
    (* ---- общие входы (заполняет PRG_Inputs) ---- *)
    xSysOnIn     : BOOL;                     (* 1K1: цепь управления включена *)
    aEStopIn     : ARRAY[1..10] OF BOOL;     (* 1 = аварийный стоп не нажат *)
    xFireOkIn    : BOOL;                     (* 1 = нет пожарной тревоги *)
    xPhaseOkIn   : BOOL;                     (* 1 = фазы в норме *)
    xFsAspPwrIn  : BOOL;
    xDryerOkIn   : BOOL;
    xComprOkIn   : BOOL;
    xCompr2OkIn  : BOOL;

    (* ---- общие флаги (PRG_System) ---- *)
    xSysOn     : BOOL;     (* цепь управления включена *)
    xGlobalOk  : BOOL;     (* цепь управления, аварийные стопы, пожар, фазы - в норме *)
    xReset     : BOOL;     (* импульс сброса аварий на один цикл *)
    xSetup     : BOOL;     (* режим наладки *)
    xStopAll   : BOOL;     (* импульс "остановить все маршруты" *)
    xPulse1s   : BOOL;     (* импульс раз в секунду на один цикл *)
    xBlink     : BOOL;     (* меандр 1 Гц *)
    xPreStart  : BOOL;     (* идёт предпусковой сигнал *)
    xAnyAlarm    : BOOL;
    xAnyNewAlarm : BOOL;
    qSiren     : BOOL;
    qLamp      : BOOL;

    (* ---- механизмы ---- *)
    aMechIn   : ARRAY[1..GVL_Const.N_MECH] OF ST_MechIn;
    aMechOut  : ARRAY[1..GVL_Const.N_MECH] OF ST_MechOut;
    aRun      : ARRAY[1..GVL_Const.N_MECH] OF BOOL;   (* механизм работает *)
    aReady    : ARRAY[1..GVL_Const.N_MECH] OF BOOL;   (* готов к работе в маршруте *)
    aAuto     : ARRAY[1..GVL_Const.N_MECH] OF BOOL;   (* в автоматическом режиме *)
    aAlarm    : ARRAY[1..GVL_Const.N_MECH] OF BOOL;
    aDemand   : ARRAY[1..GVL_Const.N_MECH] OF BOOL;   (* требуется активным маршрутом *)
    aPredRun  : ARRAY[1..GVL_Const.N_MECH] OF BOOL;   (* работает механизм, подающий на данный *)
    aSuccAuto : ARRAY[1..GVL_Const.N_MECH] OF BOOL;   (* все последующие механизмы работают *)
    aSuccMan  : ARRAY[1..GVL_Const.N_MECH] OF BOOL;   (* то же + бункеры на выходе не полны *)
    aBlocked  : ARRAY[1..GVL_Const.N_MECH] OF BOOL;   (* участок стоит на паузе по ДВУ *)

    (* ---- переключатели потока ---- *)
    aValveIn     : ARRAY[1..GVL_Const.N_VALVE] OF ST_ValveIn;
    aValveOut    : ARRAY[1..GVL_Const.N_VALVE] OF ST_ValveOut;
    aValvePos    : ARRAY[1..GVL_Const.N_VALVE] OF INT;   (* 0 - не определено, 1, 2 *)
    aValveTarget : ARRAY[1..GVL_Const.N_VALVE] OF INT;   (* задание от маршрутов *)
    aValveReady  : ARRAY[1..GVL_Const.N_VALVE] OF BOOL;
    aValveAlarm  : ARRAY[1..GVL_Const.N_VALVE] OF BOOL;

    (* ---- бункеры ---- *)
    aBunkerIn    : ARRAY[1..GVL_Const.N_BUNKER] OF ST_BunkerIn;
    aBunkerFull  : ARRAY[1..GVL_Const.N_BUNKER] OF BOOL;
    aBunkerAlarm : ARRAY[1..GVL_Const.N_BUNKER] OF BOOL;

    (* ---- связи и маршруты ---- *)
    aLinks       : ARRAY[1..GVL_Const.N_LINK] OF ST_Link;
    nLinks       : INT;
    aMember      : ARRAY[1..GVL_Const.N_ROUTE, 1..GVL_Const.N_MECH] OF BOOL;    (* состав маршрута *)
    aMemberB     : ARRAY[1..GVL_Const.N_ROUTE, 1..GVL_Const.N_BUNKER] OF BOOL;  (* бункеры маршрута *)
    aRouteCfgErr : ARRAY[1..GVL_Const.N_ROUTE] OF BOOL;
    aRouteState  : ARRAY[1..GVL_Const.N_ROUTE] OF INT;
    aRouteFault  : ARRAY[1..GVL_Const.N_ROUTE] OF BOOL;
END_VAR

(* Константы проекта ЕФБШ-649.01-АТХ, ЛПЗС-5 ССЦ "Золотой початок". Номера позиций "поз." - по технологической схеме (Приложение 1). *) VAR_GLOBAL CONSTANT N_MECH : INT := 37; N_VALVE : INT := 5; N_BUNKER : INT := 7; N_ROUTE : INT := 11; N_LINK : INT := 64; N_HEAD : INT := 6;
(* ---- механизмы (индекс = номер в панели) ---- *) M_GATE1 : INT := 1; (* заслонка бункера растаривания поз.1, ПЧ 51UZ1 *) M_N3 : INT := 2; (* нория поз.3 *) M_MUZ5_FD : INT := 3; (* МУЗ-8М поз.5 - битер (питатель), ПЧ 5UZ1 *) M_MUZ5 : INT := 4; (* МУЗ-8М поз.5 - основной двигатель *) M_FAN6 : INT := 5; (* вентилятор аспирации поз.6 *) M_SL6 : INT := 6; (* шлюзовой затвор поз.6 *) M_N7 : INT := 7; (* нория поз.7 *) M_TOR9_FD : INT := 8; (* ТОР-18 поз.9 - двигатель 0,75 кВт, ПЧ 11UZ1 *) M_TOR9 : INT := 9; (* ТОР-18 поз.9 - основной двигатель *) M_FAN10 : INT := 10; (* вентилятор аспирации поз.10 *) M_SL10 : INT := 11; (* шлюзовой затвор поз.10 *) M_N11 : INT := 12; (* нория поз.11 *) M_BT14_1 : INT := 13; (* блок триерный БТ-9/2 поз.14 - двигатель 1, ПЧ 24UZ1 *) M_BT14_2 : INT := 14; (* блок триерный БТ-9/2 поз.14 - двигатель 2, ПЧ 25UZ1 *) M_N16 : INT := 15; (* нория поз.16 *) M_KSP18_FD : INT := 16; (* КСП-11М поз.18 - битер (питатель), ПЧ 29UZ1 *) M_KSP18 : INT := 17; (* КСП-11М поз.18 - основной двигатель *) M_FAN19 : INT := 18; (* вентилятор аспирации поз.19 *) M_SL19 : INT := 19; (* шлюзовой затвор поз.19 *) M_N20 : INT := 20; (* нория поз.20 *) M_N21 : INT := 21; (* нория поз.21 *) M_SP24_DRV : INT := 22; (* СП-200 поз.24 - привод деки, ПЧ 36UZ1 *) M_SP24_FAN : INT := 23; (* СП-200 поз.24 - вентилятор стола 11 кВт (звезда-треугольник) *) M_FAN25 : INT := 24; (* вентилятор аспирации поз.25 *) M_SL25 : INT := 25; (* шлюзовой затвор поз.25 *) M_ZN26 : INT := 26; (* Z-нория поз.26, ПЧ 48UZ1 *) M_FS27 : INT := 27; (* фотосепаратор СмартСорт поз.27 *) M_FAN28 : INT := 28; (* вентилятор аспирации поз.28 *) M_SL28 : INT := 29; (* шлюзовой затвор поз.28 *) M_ZN29 : INT := 30; (* Z-нория поз.29, ПЧ 50UZ1 *) M_SH30 : INT := 31; (* конвейер шнековый КШ-4-150 поз.30 *) M_SH31 : INT := 32; (* конвейер шнековый КШU-150 поз.31 *) M_SH32 : INT := 33; (* конвейер шнековый КШU-150 поз.32 *) M_SH33 : INT := 34; (* конвейер шнековый КШU-150 поз.33 *) M_KC34 : INT := 35; (* конвейер цепной КЦСВ поз.34 *) M_KC35 : INT := 36; (* конвейер цепной КЦСН поз.35 *) M_KC36 : INT := 37; (* конвейер цепной КЦСН поз.36 *)
(* ---- переключатели потока (положение 1 / положение 2) ---- *) V_V12_1 : INT := 1; (* поз.12(1): 1 - на TORBA поз.13(1), 2 - на поз.12(2) *) V_V12_2 : INT := 2; (* поз.12(2): 1 - на БТ поз.14, 2 - на растариватель 15(1) -> нория 16 *) V_V12_3 : INT := 3; (* поз.12(3): 1 - на бункер поз.17 (КСП), 2 - на норию поз.20 *) V_V12_4 : INT := 4; (* поз.12(4): 1 - на бункер поз.22 (СП), 2 - на Z-норию поз.26 *) V_V49 : INT := 5; (* выгрузка Z-нории поз.26: 1 - включена (на TORBA 13(2)), 2 - выключена (на ФС поз.27) *)
(* ---- бункеры ---- *) B_B4 : INT := 1; (* бункер оперативный поз.4 *) B_B8 : INT := 2; (* бункер оперативный поз.8 *) B_B17 : INT := 3; (* бункер оперативный поз.17 *) B_B22 : INT := 4; (* бункер оперативный поз.22 *) B_B27 : INT := 5; (* приёмный бункер фотосепаратора поз.27 *) B_T13_1 : INT := 6; (* станция затаривания TORBA-1000 поз.13(1) *) B_T13_2 : INT := 7; (* станция затаривания TORBA-1000 поз.13(2) *)
(* ---- типы механизмов ---- *) K_DOL : INT := 0; (* прямой пуск *) K_FC : INT := 1; (* частотный преобразователь: питание, пуск, сброс *) K_GATE : INT := 2; (* заслонка с ПЧ: открыть/закрыть, концевики *) K_FS : INT := 3; (* фотосепаратор: импульсы вкл/выкл, разрешение секций *)
DKS_NONE : INT := 0; DKS_PULSE : INT := 1; (* индуктивный датчик, импульсы *) DKS_LEVEL : INT := 2; (* реле движения РДД-03, уровень 1 = движение есть *)
MODE_AUTO : INT := 0; MODE_MAN : INT := 1; MODE_LOCAL : INT := 2;
LT_MECH : INT := 0; LT_BUNKER : INT := 1; LT_INVALID : INT := 2; (* клапан не в положении - подача не определена *)
RST_IDLE : INT := 0; RST_PRESTART : INT := 1; RST_VALVES : INT := 2; RST_RUN : INT := 3; RST_STOPPING : INT := 4;
