(* ---- команды механизма (ST_MechHmi.wCmd) ---- *) C_START : WORD := 16#0001; (* пуск в ручном режиме, импульс *) C_STOP : WORD := 16#0002; (* стоп в ручном режиме, импульс *) C_MANUAL : WORD := 16#0004; (* 1 = ручной режим с панели, 0 = автомат *) C_RESET_TO : WORD := 16#0008; (* сброс счётчика ТО, импульс *) C_OPEN : WORD := 16#0010; (* заслонка: открывать, пока нажато *) C_CLOSE : WORD := 16#0020; (* заслонка: закрывать, пока нажато *)
(* ---- состояние механизма (ST_MechHmi.wSts) ---- *) S_RUN : WORD := 16#0001; S_CMD : WORD := 16#0002; S_READY : WORD := 16#0004; S_ALARM : WORD := 16#0008; S_LOCAL : WORD := 16#0010; S_MANUAL : WORD := 16#0020; S_SETUP : WORD := 16#0040; S_STARTING : WORD := 16#0080; S_STOPPING : WORD := 16#0100; S_DEMAND : WORD := 16#0200; S_PAUSE : WORD := 16#0400; S_TO_DUE : WORD := 16#0800; S_OPENED : WORD := 16#1000; S_CLOSED : WORD := 16#2000; S_SEQ_TRIP : WORD := 16#4000; (* остановлен блокировкой: встал последующий механизм *) S_SUCC_OK : WORD := 16#8000; (* последующие механизмы в работе - ручной пуск разрешён *)
