(* ---- отключение датчиков (ST_MechHmi.wBypass / ST_BunkerHmi.wBypass) ---- *) BY_DKS : WORD := 16#0001; BY_DSL1 : WORD := 16#0002; BY_DSL2 : WORD := 16#0004; BY_DP : WORD := 16#0008; BY_AUX : WORD := 16#0010; (* фотосепаратор: не требовать работу компрессора *) BY_DVU : WORD := 16#0001; (* бункер: ДВУ отключен *)
