(* ---- бункеры ---- *) BS_DVU : WORD := 16#0001; (* ДВУ сработал (без задержки) *) BS_FULL : WORD := 16#0002; (* бункер полон - пауза подачи *) BS_DNU : WORD := 16#0004; BS_BYPASS : WORD := 16#0008; BS_ALARM : WORD := 16#0010; BA_SF : WORD := 16#0001; (* TORBA: отключен автомат пульта управления *)
